config.script:
try:
    atsThemeLibrary.load_into(self.view, self.view.custom.sourceTheme)
except Exception as e:
    self.view.custom.status = "Error: " + str(e)

try:
    self.view.custom.themeOptions = atsThemeLibrary.theme_options()
    self.view.custom.status = "Lista actualizada."
except Exception as e:
    self.view.custom.status = "Error: " + str(e)

try:
    if event.column == "value":
        atsThemeLibrary.edit(self.view, int(event.row), event.value)
except Exception as e:
    self.view.custom.status = "Error: " + str(e)

try:
    rows = atsThemeLibrary.plain(self.view.custom.rows)
    content = atsThemeLibrary.export_zip(self.view.custom.targetName, self.view.custom.baseTheme, rows)
    system.perspective.download(self.view.custom.targetName + ".zip", bytearray(content), "application/zip")
except Exception as e:
    self.view.custom.status = "Error: " + str(e)

try:
    table = self.parent.parent.getChild("Workspace").getChild("Variables")
    index = table.props.selection.selectedRow
    if index is None or int(index) < 0:
        raise ValueError("Selecciona una fila de la tabla.")
    atsThemeLibrary.edit(self.view, int(index), "")
except Exception as e:
    self.view.custom.status = "Error: " + str(e)

try:
    atsThemeLibrary.load_into(self.view, "light")
    self.view.custom.themeOptions = atsThemeLibrary.theme_options()
except Exception as e:
    self.view.custom.status = "Error: " + str(e)
